# Initial lambda search: constant-residual extremal geometry supplies candidates.
def H(j):
    return sp.S(0) if j == 0 else sp.Rational(j*j + 5*j + 2, 8)
def a(j, n):
    if j == 0:
        return sp.S(0)
    B = sp.Rational(j*(j+3), 4) - sp.Rational(j*(j-1)*(j+1)*(j+2), 8*n*(n+1))
    return B / (2*H(n)-H(j))
def b(j, n):
    return a(j, n) / (2*H(n)-H(j)+1)

guesses = {c.name: sp.S(0) for c, *_ in inventory(ctx, pb) if c.name not in pb.relaxed_constraints}
guesses["initial_condition"] = 1/(4*H(N))
def add_guess(owner, u, v, value):
    if ctx[u] is not ctx[v]:
        guesses[f"{owner}:{ctx[u]},{ctx[v]}"] += value
for j in range(1, N+1):
    aj, ap, bj = a(j, N), a(j-1, N), b(j, N)
    add_guess("g", "x_star", f"y_{j}", aj-ap)
    add_guess("f", "x_star", f"x_{j-1}", aj-ap-bj)
    add_guess("f", "x_star", f"y_{j}", bj)
    add_guess("f", f"x_{j-1}", f"y_{j}", aj-bj)
    if j > 1:
        add_guess("g", f"y_{j-1}", f"y_{j}", ap)
        add_guess("f", f"y_{j-1}", f"x_{j-1}", ap)
candidate_errors = {key: abs(float(value) - certificate["named_dual_values"][key]) for key, value in guesses.items()}
print("lambda candidate max error", max(candidate_errors.values()), flush=True)
for j in range(1, N+1):
    print("a,b", j, a(j,N), b(j,N), flush=True)
